public class {{className}} extends WorldFeature {

	@Override
	public boolean place(World world, Random random, int x, int y, int z) {
		// The same gate every vanilla tree uses (javap'd from
		// WorldFeatureTree.place). The heightmap counts leaves, so placement
		// attempts land on canopy tops; without this a tree happily plants
		// on another tree. A canopy is not ground that GROWS_TREES.
		if (!Blocks.hasTag(world.getBlockId(x, y - 1, z), BlockTags.GROWS_TREES)) {
			return false;
		}

		int height = {{minHeight}} + random.nextInt({{heightRange}});

		// trunk
		for (int dy = 0; dy < height; dy++) {
			world.setBlockWithNotify(x, y + dy, z, {{logBlock}}.id());
		}

		// leaf canopy: 2-layer blob around the crown
		for (int dy = height - 2; dy <= height + 1; dy++) {
			int radius = dy > height - 1 ? 1 : 2;
			for (int dx = -radius; dx <= radius; dx++) {
				for (int dz = -radius; dz <= radius; dz++) {
					if (Math.abs(dx) == radius && Math.abs(dz) == radius && random.nextBoolean()) continue;
					if (world.getBlockId(x + dx, y + dy, z + dz) == 0) {
						world.setBlockWithNotify(x + dx, y + dy, z + dz, {{leavesBlock}}.id());
					}
				}
			}
		}
		return true;
	}
}

