private static void spawn(Biome biome, Class<? extends Mob> entity, int weight, boolean hostile) {
	if (biome == null) {
		return;
	}
	try {
		java.lang.reflect.Field field = Biome.class.getDeclaredField(hostile ? "spawnableMonsterList" : "spawnableCreatureList");
		field.setAccessible(true);
		@SuppressWarnings("unchecked")
		java.util.List<SpawnListEntry> list = (java.util.List<SpawnListEntry>) field.get(biome);
		list.add(new SpawnListEntry(entity, weight));
	} catch (ReflectiveOperationException | RuntimeException e) {
		LOGGER.error("Could not add a spawn entry to biome {}.", biome.translationKey, e);
	}
}

