@Override
public void updateTick(World world, TilePosc pos, Random rand, boolean isInitial) {
	super.updateTick(world, pos, rand, isInitial);
	if (world.getBlockType(pos) != this.block) {
		return;
	}
	TilePos above = pos.up(new TilePos());
	if (!world.isAirBlock(above)) {
		return;
	}
	// count the stack under this segment, growth stops at the cap
	int height = 1;
	TilePos below = new TilePos(pos);
	below.y--;
	while (world.getBlockType(below) == this.block) {
		height++;
		below.y--;
	}
	if (height >= {{maxHeight}}) {
		return;
	}
	// the sugarcane clock: block data counts ticks, a wrap grows a segment
	int age = world.getBlockData(pos) + 1 & 15;
	world.setBlockData(pos, age);
	if (age == 0) {
		world.setBlockTypeNotify(above, this.block);
	}
}

