public class {{className}} extends BiomeProvider {

	/** cell size in blocks; deliberately broad, biomes are places not speckle */
	private static final int CELL = 96;
	/** how far the warp may push a sample off the grid, half a cell */
	private static final double WARP_AMPLITUDE = CELL / 2.0;
	private static final double WARP_SCALE = 1.0 / 320.0;
	private static final int COUNT = {{count}};

	private final FractalNoise2D<?> warpNoise;
	private final long seed;

	public {{className}}(World world) {
		super(world);
		this.seed = world.getRandomSeed();
		// its own seed multiplier so the warp shares no structure with anything else
		this.warpNoise = new FractalNoise2D<>(SimplexNoise.genOctaves(this.seed * 6449L, 3));
	}

	/** the roster in a fixed order; slotAt indexes into it */
	private Biome[] roster() {
		return new Biome[] { {{roster}} };
	}

	/**
	 * Which biome owns this column: a hash draw over a warped cell. A draw,
	 * not a threshold, so nothing about slot 0 makes it likelier to border
	 * slot 1 than the last one.
	 */
	private int slotAt(int x, int z, double warpX, double warpZ) {
		int cellX = MathHelper.floor((x + warpX) / (double) CELL);
		int cellZ = MathHelper.floor((z + warpZ) / (double) CELL);
		long h = this.seed;
		h = h * 6364136223846793005L + (cellX * 0x9E3779B97F4A7C15L);
		h = h * 6364136223846793005L + (cellZ * 0xC2B2AE3D27D4EB4FL);
		h ^= (h >>> 33);
		h *= 0xFF51AFD7ED558CCDL;
		h ^= (h >>> 33);
		return (int) Math.floorMod(h, (long) COUNT);
	}

	@Override
	public Biome[] getBiomes(Biome[] biomes, double[] temperatures, double[] humidities, double[] varieties, int x, int y, int z, int xSize, int ySize, int zSize) {
		if (biomes == null || biomes.length != xSize * ySize * zSize) {
			biomes = new Biome[xSize * ySize * zSize];
		}
		double[] warpA = this.warpNoise.getRegion(null, x, z, xSize, zSize, WARP_SCALE, WARP_SCALE);
		double[] warpB = this.warpNoise.getRegion(null, x + 4093, z - 2711, xSize, zSize, WARP_SCALE, WARP_SCALE);
		Biome[] roster = roster();
		for (int xx = 0; xx < xSize; xx++) {
			for (int zz = 0; zz < zSize; zz++) {
				int i = xx * zSize + zz;
				int slot = slotAt(x + xx, z + zz, warpA[i] * WARP_AMPLITUDE, warpB[i] * WARP_AMPLITUDE);
				for (int yy = 0; yy < ySize; yy++) {
					biomes[(xx * zSize + zz) * ySize + yy] = roster[slot];
				}
			}
		}
		return biomes;
	}

	/** per-column climate from the owning biome, so the colormap follows it */
	private double[] fillFromBiomes(double[] out, int x, int z, int xSize, int zSize, boolean humidity) {
		if (out == null || out.length < xSize * zSize) {
			out = new double[xSize * zSize];
		}
		double[] warpA = this.warpNoise.getRegion(null, x, z, xSize, zSize, WARP_SCALE, WARP_SCALE);
		double[] warpB = this.warpNoise.getRegion(null, x + 4093, z - 2711, xSize, zSize, WARP_SCALE, WARP_SCALE);
		Biome[] roster = roster();
		for (int xx = 0; xx < xSize; xx++) {
			for (int zz = 0; zz < zSize; zz++) {
				int i = xx * zSize + zz;
				Biome biome = roster[slotAt(x + xx, z + zz, warpA[i] * WARP_AMPLITUDE, warpB[i] * WARP_AMPLITUDE)];
				out[i] = humidity ? biome.defaultHumidity : biome.defaultTemperature;
			}
		}
		return out;
	}

	@Override
	public double[] getTemperatures(double[] temperatures, int x, int z, int xSize, int zSize) {
		return fillFromBiomes(temperatures, x, z, xSize, zSize, false);
	}

	@Override
	public double[] getHumidities(double[] humidities, int x, int z, int xSize, int zSize) {
		return fillFromBiomes(humidities, x, z, xSize, zSize, true);
	}

	@Override
	public double[] getVarieties(double[] varieties, int x, int z, int xSize, int zSize) {
		if (varieties == null || varieties.length < xSize * zSize) {
			varieties = new double[xSize * zSize];
		}
		double[] warpA = this.warpNoise.getRegion(null, x, z, xSize, zSize, WARP_SCALE, WARP_SCALE);
		double[] warpB = this.warpNoise.getRegion(null, x + 4093, z - 2711, xSize, zSize, WARP_SCALE, WARP_SCALE);
		for (int xx = 0; xx < xSize; xx++) {
			for (int zz = 0; zz < zSize; zz++) {
				int i = xx * zSize + zz;
				varieties[i] = slotAt(x + xx, z + zz, warpA[i] * WARP_AMPLITUDE, warpB[i] * WARP_AMPLITUDE) / (double) (COUNT - 1);
			}
		}
		return varieties;
	}

	@Override
	public double[] getBiomenesses(double[] biomenesses, int x, int y, int z, int xSize, int ySize, int zSize) {
		if (biomenesses == null || biomenesses.length < xSize * ySize * zSize) {
			biomenesses = new double[xSize * ySize * zSize];
		}
		java.util.Arrays.fill(biomenesses, 1.0);
		return biomenesses;
	}

	/**
	 * Position-free lookup, for callers holding a climate but no coordinates.
	 * Variety is the only axis carrying the slot, so it reads that back.
	 */
	@Override
	public Biome lookupBiome(double temperature, double humidity, double altitude, double variety) {
		Biome[] roster = roster();
		int slot = (int) Math.round(Math.max(0.0, Math.min(1.0, variety)) * (COUNT - 1));
		return roster[Math.max(0, Math.min(COUNT - 1, slot))];
	}
}

