public final class ModDimensions {

{{decls}}

	/** Forces static initialization. Called from the mod entrypoint. */
	public static void init() {}

	/**
	 * Dimension.portalBlock is final and BlockLogicPortal's constructor takes
	 * the Dimension, so the two cannot both be satisfied by construction.
	 * Vanilla's own NETHER pair settles the same cycle by class-init order; a
	 * mod cannot, so the field is set by reflection once both halves exist.
	 * Load-bearing, not cosmetic: PortalHandler dereferences
	 * newDim.portalBlock on every journey in either direction.
	 */
	public static void attachPortals() {
{{attaches}}	}

	private static void attach(Dimension dimension, Block<?> portal) {
		try {
			java.lang.reflect.Field field = Dimension.class.getField("portalBlock");
			field.setAccessible(true);
			field.set(dimension, portal);
		} catch (ReflectiveOperationException | RuntimeException e) {
			LOGGER.error("Could not attach a portal block; travel to that dimension will fail.", e);
		}
	}

	/**
	 * Claims the dimension ids, once the game's own Dimension.init() has
	 * claimed 0 to 2. On a client this runs from afterGameStart; a dedicated
	 * server builds every WorldServer before that event fires, so a mixin
	 * also calls it from startServer right after Dimension.init(). It runs
	 * twice on a server and must stay idempotent.
	 */
	public static void register() {
{{registers}}	}

	private static void registerOne(int id, Dimension dimension, WorldType type) {
		Dimension existing = Dimension.getDimensionList().get(id);
		if (existing == dimension) {
			return;
		}
		if (existing != null) {
			LOGGER.error("Dimension id {} is already taken; change starting_dimension_id in the config.", id);
			return;
		}
		Dimension.registerDimension(id, dimension);
		// Every world-type group snapshotted its dimension map before this
		// dimension existed, and Group.get is a requireNonNull: an unseeded
		// group kills a server in initWorld and a client at world creation.
		for (WorldTypeGroups.Group group : WorldTypeGroups.GROUPS) {
			group.with(dimension, type);
		}
	}
}

