@Mixin(value = MinecraftServer.class, remap = false)
public class {{className}} {

	/**
	 * The only window a dedicated server offers: after the game's own
	 * Dimension.init() (any earlier and the ids collide with it), and before
	 * startServer builds a WorldServer, a PlayerManager and an entity tracker
	 * per registered dimension. afterGameStart fires at the TAIL of this
	 * method, after all three maps have closed: a dimension registered there
	 * has no world behind it, and one portal step bricks the player who took
	 * it.
	 */
	@Inject(
		method = "startServer",
		at = @At(value = "INVOKE", target = "Lnet/minecraft/core/world/Dimension;init()V", shift = At.Shift.AFTER)
	)
	private void artemisRegisterDimensions(CallbackInfoReturnable<Boolean> cir) {
		ModDimensions.register();
	}
}
